                            (ar_idt_trace[ar_idt_widx] == fub_axi_artrace));
    assign ar_gate_ok = ar_id_ok && !ar_trk_full;

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign r_slave_select = 3'b001;

    // bridge BUG-010: the R echoes its request's trace (an atomic's AW trace).
    logic r_trk_trace;
    assign r_trk_trace = ar_idt_trace[ar_idt_ridx];

    // AR-ready MUX (request side: uses combinational comb_slave_select_ar)
    always_comb begin
        fub_axi_arready = 1'b0;
        case (comb_slave_select_ar)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_arready = cpu_rd_32b_arready;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_arready = cpu_rd_32b_arready;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_arready = cpu_rd_32b_arready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AR the gate refuses (see ar_gate_ok).
        if (!ar_gate_ok) fub_axi_arready = 1'b0;
    end

    // Read response MUX (R channel - uses r_slave_select FIFO head)
    // rtrace is NOT driven here -- see the B-channel note (bridge BUG-010, was BRIDGE-012).
    logic r_slave_trace;
    always_comb begin
        fub_axi_rid = 4'd0;
        fub_axi_rdata = 32'd0;
        fub_axi_rresp = 2'b00;
        fub_axi_rlast = 1'b0;
        fub_axi_rvalid = 1'b0;
        r_slave_trace = '0;  // AXI5 sideband (trace)

        case (r_slave_select)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_rid = cpu_rd_32b_r.id[3:0];
                fub_axi_rdata = cpu_rd_32b_r.data;
                fub_axi_rresp = cpu_rd_32b_r.resp;
                fub_axi_rlast = cpu_rd_32b_r.last;
                fub_axi_rvalid = cpu_rd_32b_rvalid;
                r_slave_trace = cpu_rd_32b_r.trace;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_rid = cpu_rd_32b_r.id[3:0];
                fub_axi_rdata = cpu_rd_32b_r.data;
                fub_axi_rresp = cpu_rd_32b_r.resp;
                fub_axi_rlast = cpu_rd_32b_r.last;
                fub_axi_rvalid = cpu_rd_32b_rvalid;
                r_slave_trace = cpu_rd_32b_r.trace;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_rid = cpu_rd_32b_r.id[3:0];
                fub_axi_rdata = cpu_rd_32b_r.data;
                fub_axi_rresp = cpu_rd_32b_r.resp;
                fub_axi_rlast = cpu_rd_32b_r.last;
                fub_axi_rvalid = cpu_rd_32b_rvalid;
                r_slave_trace = cpu_rd_32b_r.trace;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end


    // bridge BUG-010 (was BRIDGE-012): the port promises trace; echo the request's bit.
    assign fub_axi_rtrace = r_trk_trace;

`ifndef SYNTHESIS
