            |(r_slave_select & R_TRACE_CAPABLE) &&
            (r_slave_trace !== r_trk_trace)) begin
            $error("%m: bridge BUG-010 (was BRIDGE-012): trace-capable slave returned rtrace=%b for a request with trace=%b",
